IF  EXISTS(select 1 from sys.views where name='VW_SAPHANA_MSSL_ROLES')
BEGIN
DROP VIEW  [dbo].[VW_SAPHANA_MSSL_ROLES]
END
GO

--VW_MSSLISU_CRM_ROLES

CREATE VIEW [dbo].[VW_SAPHANA_MSSL_ROLES]
AS
SELECT Distinct  SAPR.Id as SAP_ROLEID,SAPR.EndpointSystemId, A.BusinessRole,SAPR.ROLE_CODE,SAPR.ROLE_DESC, SAPR.EndpointUserId, SAPR.ValidToDate,BusinessRole as Description
FROM
(SELECT RoleName as BusinessRole,item AS Technicalrole from DI_SAPHANA_XLRolesMatrix cross apply dbo.Split(TechnicalRole,',') WHERE item!='') 
AS A INNER JOIN
(SELECT Distinct rinfo.Id,ruinfo.EndpointSystemId, ruinfo.SAPHANAUserinfo_Id as EndpointUserId,rinfo.ROLE_CODE,rinfo.ROLE_DESC,
CASE WHEN ISDATE(ruinfo.Role_ToDate)=1 THEN Convert(date,ruinfo.Role_ToDate,111) ELSE NULL End as ValidToDate
FROM SAPHANARoleInfoSAPHANAUserinfo ruinfo join DI_SAPHANA_ROLEINFO rinfo ON ruinfo.SAPHANARoleInfo_Id = rinfo.Id AND ruinfo.IsDirectlyAttached = 1 
INNER JOIN DI_M_EndpointSystem E on ruinfo.EndpointSystemId = E.Id
WHERE E.ApplicationType IN(42))as SAPR on A.Technicalrole = SAPR.ROLE_CODE

GO
IF  EXISTS(select 1 from sys.views where name='VW_SAPHANA_EBS_ROLES')
BEGIN
DROP VIEW  [dbo].[VW_SAPHANA_EBS_ROLES]
END
GO

CREATE VIEW [dbo].[VW_SAPHANA_EBS_ROLES]
AS
SELECT Distinct  SAPR.Id as SAP_ROLEID,SAPR.EndpointSystemId, A.BusinessRole,SAPR.ROLE_CODE,SAPR.ROLE_DESC, SAPR.EndpointUserId, SAPR.ValidToDate,BusinessRole as Description
FROM
(SELECT RoleName as BusinessRole,item AS Technicalrole from DI_SAPHANA_XLRolesMatrix cross apply dbo.Split(TechnicalRole,',') WHERE item!='') 
AS A INNER JOIN
(SELECT Distinct rinfo.Id, ruinfo.EndpointSystemId, ruinfo.SAPHANAUserinfo_Id as EndpointUserId,rinfo.ROLE_CODE,rinfo.ROLE_DESC,CASE WHEN ISDATE(ruinfo.Role_ToDate)=1 THEN Convert(date,ruinfo.Role_ToDate,111) ELSE NULL End as ValidToDate
FROM SAPHANARoleInfoSAPHANAUserinfo ruinfo join DI_SAPHANA_ROLEINFO rinfo ON ruinfo.SAPHANARoleInfo_Id = rinfo.Id AND ruinfo.IsDirectlyAttached = 1 
INNER JOIN DI_M_EndpointSystem E on ruinfo.EndpointSystemId = E.Id
WHERE E.ApplicationType IN(41))as SAPR on A.Technicalrole = SAPR.ROLE_CODE
GO

IF  EXISTS(select 1 from sys.objects where name='USP_SAPHANA_INDIRECTROLE')
BEGIN
DROP PROC  [dbo].USP_SAPHANA_INDIRECTROLE
END
GO

CREATE PROC [dbo].USP_SAPHANA_INDIRECTROLE
(
@ENDPOINTSYSTEMID BIGINT,
@ACCOUNTRECONID BIGINT
)
AS
BEGIN
			SELECT R.Id,R.EndPointSystemId,U.Id as EndpointUserId,R.ROLE_CODE as BusinessRole,R.ROLE_DESC as Description,
			CASE WHEN ISNULL(UR.Role_ToDate,'')!='' THEN CAST(UR.Role_ToDate as DateTime) ELSE NULL End as ValidToDate,null as Company,
			NULL AS Module, NULL AS SubModule,NULL as Remarks 
			FROM SAPHANARoleInfoSAPHANAUserinfo UR INNER JOIN   DI_SAPHANA_UserInfo U on UR.SAPHANAUserinfo_Id = U.Id  
			INNER JOIN DI_SAPHANA_ROLEINFO R on UR.SAPHANARoleInfo_Id = R.Id 
			INNER JOIN DI_M_AccountReconcilation AR ON U.ID = AR.EndpointUserId 
            WHERE AR.ID = @ACCOUNTRECONID AND  AR.EndpointSystemId=@ENDPOINTSYSTEMID  AND  
			UR.EndpointSystemId=@ENDPOINTSYSTEMID AND UR.IsDirectlyAttached = 0 and U.EndPointSystemId=@ENDPOINTSYSTEMID AND 
			R.EndPointSystemId=@ENDPOINTSYSTEMID

END
GO

IF  EXISTS(select 1 from sys.objects where name='USP_SAPHANA_INDIRECTROLE_BYPOSITION')
BEGIN
DROP PROC  [dbo].USP_SAPHANA_INDIRECTROLE_BYPOSITION
END
GO
CREATE PROC [dbo].[USP_SAPHANA_INDIRECTROLE_BYPOSITION]
(
@ENDPOINTSYSTEMID BIGINT,
@USERNAME VARCHAR(128),
@POSITIONCODE VARCHAR(MAX)=''
)
AS
BEGIN

		SELECT R.Id,R.EndPointSystemId,U.Id as EndpointUserId,R.ROLE_CODE as BusinessRole,R.ROLE_DESC as Description,CASE WHEN ISDATE(UR.Role_ToDate)=1 THEN 
		CAST(UR.Role_ToDate as DateTime) ELSE NULL End as ValidToDate,null as Company,NULL AS Module, NULL AS SubModule,NULL as Remarks
		FROM DI_SAPHANA_SAPHRP1001 H inner join DI_SAPHANA_ROLEINFO R on H.RelatedObjectCode = R.ROLE_CODE INNER JOIN SAPHANARoleInfoSAPHANAUserinfo UR on R.Id = UR.SAPHANARoleInfo_Id
		INNER JOIN DI_SAPHANA_UserInfo U on UR.SAPHANAUserinfo_Id = U.Id
		WHERE  H.ActualObjectCode=@POSITIONCODE and H.RelatedObjectType='AG'  AND 
		U.UserLogonName = @USERNAME AND  H.EndpointSystemId=@ENDPOINTSYSTEMID AND  
		UR.EndpointSystemId=@ENDPOINTSYSTEMID AND UR.IsDirectlyAttached =0    AND 
		U.EndPointSystemId=@ENDPOINTSYSTEMID AND R.EndPointSystemId=@ENDPOINTSYSTEMID

END
GO


IF  EXISTS(select 1 from sys.objects where name='fnSAPHANAGetRoleFromPosition')
BEGIN
DROP FUNCTION  [dbo].[fnSAPHANAGetRoleFromPosition] 
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		SIVANANDAN
-- Create date: 21 MAY 2024
-- Description:	GET THE INDIRECT ROLES BY POSITION FOR SPECIFIED ENDPOINT
-- example select * from DBO.[fnSAPHANAGetRoleFromPosition](10,50000352) 
-- =============================================
CREATE FUNCTION [dbo].[fnSAPHANAGetRoleFromPosition] 
(	
	@ENDPOINTID bigint,
	@POS nvarchar(512)
)
RETURNS @ROLES TABLE(POSITION NVARCHAR(512),ROLE NVARCHAR(MAX) NULL,DESCR NVARCHAR(MAX) NULL) 
AS
BEGIN

	
	INSERT INTO @ROLES(POSITION,ROLE,DESCR)
	SELECT @POS,RelatedObjectCode,ROLE_DESC FROM (SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId = @ENDPOINTID AND ActualObjectCode = @POS AND RelatedObjectType='AG' AND ActualObjectType='S')AS A
	INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID
	--GetOrgByPosition--
	DECLARE @ORGUNIT NVARCHAR(512)=''
	SET @ORGUNIT  = (SELECT  TOP 1 RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND ActualObjectCode = @POS AND RelatedObjectType='O' AND ActualObjectType='S')

	IF LEN(ISNULL(@ORGUNIT,'')) > 0
	BEGIN
							
	--getrolesbyorg--
	INSERT INTO @ROLES(POSITION,ROLE,DESCR)
	SELECT @POS,RelatedObjectCode,ROLE_DESC FROM
	(SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectType='AG' AND ActualObjectType='O' AND ActualObjectCode = @ORGUNIT
	) AS A INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID
	--GETPARENTOTGBYORG
	SET @ORGUNIT  = (SELECT  TOP 1 ActualObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectCode = @ORGUNIT AND RelatedObjectType='O' AND ActualObjectType='O')

	END

	DECLARE @INCRE INT = 0
	DECLARE @ISPARENTEXISTS BIT = 1
	WHILE(@ISPARENTEXISTS = 1 AND LEN(ISNULL(@ORGUNIT,'')) > 0)
	BEGIN
			SET @INCRE = @INCRE + 1
			IF(@INCRE <= 5 AND LEN(ISNULL(@ORGUNIT,'')) > 0)
			BEGIN
					INSERT INTO @ROLES(POSITION, ROLE,DESCR)
					SELECT @POS,RelatedObjectCode,ROLE_DESC FROM
					(SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectType='AG' AND ActualObjectType='O' AND ActualObjectCode = @ORGUNIT
					) AS A INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID

					SET @ORGUNIT  = (SELECT  TOP 1 ActualObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectCode = @ORGUNIT AND RelatedObjectType='O' AND ActualObjectType='O')

			END
			ELSE 
			BEGIN
				SET @ISPARENTEXISTS = 0
			END
	END
	RETURN
END
GO
