IF  EXISTS(select 1 from sys.objects where name='USP_GetSAPHANA_SODConflicts')
BEGIN
DROP PROC  [dbo].USP_GetSAPHANA_SODConflicts
END
GO

CREATE PROC [dbo].[USP_GetSAPHANA_SODConflicts]
(
@userId BIGINT,
@currentRequestId BIGINT,
@isCurrentBulkRequest BIT=0,
@applicationType NVARCHAR(MAX),
@inGrid bit= 1,
@debug bit=0
)
AS
BEGIN
	
	BEGIN TRY 
	SET NOCOUNT ON;
	--declare @flinsApplicationType int 
	DECLARE @AdhocActionType INT
	DECLARE @progressStatus BIGINT
	DECLARE @ACCOUNTTYPE TINYINT

	DECLARE @tblCurrentRequestTabContent TABLE(id INT IDENTITY,    xmlcontent XML)
	DECLARE @tblExistingXmlContent TABLE(id INT IDENTITY,RequestId INT,[source] NVARCHAR(500), xmlcontent XML NULL,ENDPOINTNAME NVARCHAR(MAX) null,ENDPOINTID NVARCHAR(MAX) null,ApplicationType int null)
	DECLARE @tblExistingRequestEntitlements TABLE(id INT IDENTITY,[SOURCE] NVARCHAR(500),RequestId INT,Entitlement NVARCHAR(1000),TECHNICALROLE NVARCHAR(MAX) NULL,POSITION NVARCHAR(MAX) NULL,ENDPOINTNAME NVARCHAR(MAX) null,ENDPOINTID NVARCHAR(MAX) null,ApplicationType int null)
	DECLARE @tblCurrentRequestEntitlements TABLE(id INT IDENTITY,Entitlement  NVARCHAR(MAX))
	DECLARE @tblCurrentAccess TABLE(id INT IDENTITY,[SOURCE] NVARCHAR(500),RequestId INT,Entitlement NVARCHAR(1000),TECHNICALROLE NVARCHAR(MAX) NULL,POSITION NVARCHAR(MAX) NULL,ENDPOINTNAME NVARCHAR(MAX) null,ENDPOINTID NVARCHAR(MAX) null,ApplicationType int null)

	DECLARE @tblCRequestRole TABLE(id INT IDENTITY,POSITION  NVARCHAR(MAX),TechnicalRole NVARCHAR(MAX), BUSINESSROLE NVARCHAR(MAX) NULL, ENDPOINTNAME NVARCHAR(MAX),EP_CODE NVARCHAR(32) NULL)
	
	--DECLARE @tbldependent_CRequestRole TABLE(id INT IDENTITY,POSITION  NVARCHAR(MAX),TechnicalRole NVARCHAR(MAX), BUSINESSROLE NVARCHAR(MAX) NULL, ENDPOINTNAME NVARCHAR(MAX))

	DECLARE @tblConflictBRoles TABLE(id INT IDENTITY, BRole  NVARCHAR(MAX)NULL,TRole  NVARCHAR(MAX)NULL,CBRole  NVARCHAR(MAX) NULL,CTRole  NVARCHAR(MAX) NULL,ConflictingRemarks NVARCHAR(MAX) NULL,Position NVARCHAR(MAX) NULL, ENDPOINTNAME NVARCHAR(MAX),EP_APPLNCODE NVARCHAR(32) NULL, FROMCurrentRequestPosition bit default(0))
  
	DECLARE @RESULT TABLE(ID INT IDENTITY(1,1), EndpointName nvarchar(512) null,RequestedRole nvarchar(max) null,ConflictedRole nvarchar(max) null,ConflictRemarks nvarchar(max) null,[Source] nvarchar(512) null,[ReqRoleForSorting] nvarchar(512) null)
	
	DECLARE @endpointUserId INT = 0
	DECLARE @i INT =  0
	DECLARE @splitter nvarchar(1) = ','
	DECLARE @XMLCONTENT XML 
	DECLARE @count INT
	DECLARE @applicationTypeXML NVARCHAR(MAX) 
	DECLARE @positionText NVARCHAR(200) 
	DECLARE @applicationName NVARCHAR(100)
	DECLARE @endpointSystemId INT =0 
	SET @AdhocActionType = 1  
	SET @progressStatus  = 1  
    DECLARE @endpointsystem NVARCHAR(MAX) = ''
	DECLARE @ISCOMPLETEDREQUEST BIT = 0
	SET @i=0  
	SET @endpointUserId   = 0 
	DECLARE @POSITIONS_TBL TABLE(POSITION VARCHAR(MAX));
	DECLARE @TEMP_POS_CODE NVARCHAR(64)=''	

	IF @isCurrentBulkRequest = 0
	BEGIN
		SELECT @endpointSystemId =  EndpointSystemId,@ACCOUNTTYPE=AccountType FROM DI_M_AdHocAccessRequest WHERE id = @currentRequestId
		SELECT @ISCOMPLETEDREQUEST = CASE WHEN (ProgressStatus = 5 OR ProgressStatus=10 OR ProgressStatus=8  OR ProgressStatus=2) THEN 1 ELSE 0 END FROM DI_M_AccessRequest WHERE AdHocAccessRequestId = @currentRequestId
	END
	ELSE
	BEGIN
			---BULK REQUEST FOR USER ACCOUNT ONLY
			SELECT @endpointSystemId =  EndpointSystemId,@ISCOMPLETEDREQUEST = CASE WHEN (ProgressStatus = 5 OR ProgressStatus=10 OR ProgressStatus=8 OR ProgressStatus=2) THEN 1 ELSE 0 END FROM DI_M_BulkRequest WHERE id = @currentRequestId
			SET @ACCOUNTTYPE = 1;
	END
	
	DECLARE @REALLOCATE NVARCHAR(10)='false';
	declare @applnType tinyint=0
	
	SELECT @applnType =  ApplicationType,@endpointsystem = DisplayName FROM DI_M_EndpointSystem where Id = @endpointSystemId
	
	DECLARE @ACCOUNTNAME NVARCHAR(512)=''
	
	-----GET ENTITLEMENT DETAILS FROM CURRENT REQUEST -----
	IF @isCurrentBulkRequest = 0
	BEGIN

		SELECT @AdhocActionType = adhoc.AdhocActionType	FROM DI_M_AccessRequest AS accrrst join DI_M_AdHocAccessRequest AS adhoc ON accrrst.AdHocAccessRequestId = adhoc.Id 
		WHERE  adhoc.Id = @currentRequestId    
		INSERT INTO @tblCurrentRequestTabContent (xmlcontent) 
		( 
			SELECT  cast( adhoc.EntitlementDetail as XML)  FROM DI_M_AccessRequest AS accrrst join DI_M_AdHocAccessRequest AS adhoc ON accrrst.AdHocAccessRequestId = adhoc.Id 
			WHERE  adhoc.Id = @currentRequestId    
		)
	END
	ELSE
	BEGIN
		SELECT @AdhocActionType = AdhocActionType,@endpointUserId = BLKD.EndpointUserId 
		FROM DI_M_BulkRequest AS bulkReq  INNER JOIN DI_M_BulkRequestDetail BLKD ON bulkReq.ID = BLKD.BulkRequestId 
		WHERE  bulkReq.Id = @currentRequestId AND BLKD.UserId = @userId    
		 
		INSERT INTO @tblCurrentRequestTabContent (xmlcontent) 
		(	 
			SELECT  cast(bulkReq.EntitlementDetail as XML) FROM DI_M_BulkRequest AS bulkReq
			WHERE  Id =  @currentRequestId 
		)
	END 


	DECLARE @CURRENT_APPln NVARCHAR(500)


	DECLARE @MODULE NVARCHAR(500)=''
	
	SET @applicationTypeXML = 'AdHocSAPHANARequest'
	SELECT @CURRENT_APPln = ApplicationCode FROM DI_M_EndpointSystem WHERE Id = @endpointSystemId
	SET @applicationName = @CURRENT_APPln
	

	SELECT  @XMLCONTENT =  xmlcontent FROM @tblCurrentRequestTabContent; 
 
	---FETCH CURRENT REQUEST ROLES
	INSERT INTO @tblCurrentRequestEntitlements  
	SELECT DISTINCT   REPLACE(B.Item,CHAR(9),'') FROM 
	(SELECT Field.N.value('(Roles/text())[1]', 'nvarchar(500)') As Roles FROM 
	@XMLCONTENT.nodes('/*[local-name()=sql:variable("@applicationTypeXML")]') as Field (N) ) A CROSS APPLY dbo.split(A.Roles,@splitter) B
	

	IF @isCurrentBulkRequest <> 1
	BEGIN
			SELECT @endpointUserId =  E.EndpointUserId FROM 
			(
				SELECT Field.N.value('(text())[1]', 'nvarchar(500)') AS EndpointUserId FROM 
				@XMLCONTENT.nodes('/*[local-name()=sql:variable("@applicationTypeXML")]/EndpointUserId') as Field (N) 
			)AS  E
	END
	
	DECLARE @POSPREFIX NVARCHAR(512)=''
	SET @POSPREFIX = ''
	DECLARE @CURRENT_APPLN_TYPENAME NVARCHAR(32)
	SET @CURRENT_APPLN_TYPENAME = @CURRENT_APPln
			
	---GET CURRENT REQUEST ROLE AND INDIRECT ROLE FROM POSITION---
	SELECT @ACCOUNTNAME =  E.AccName FROM 
	(
	SELECT Field.N.value('(text())[1]', 'nvarchar(500)') AS AccName FROM 
	@XMLCONTENT.nodes('/AdHocSAPHANARequest/AccName') AS Field (N) ) E

			

	SELECT @REALLOCATE =  E.IsReallocate FROM 
	(
	SELECT Field.N.value('(text())[1]', 'nvarchar(500)') AS IsReallocate FROM 
	@XMLCONTENT.nodes('/AdHocSAPHANARequest/IsReallocate') AS Field (N) ) E

	SELECT @POSPREFIX =  E.PositionPrefix FROM 
	(
	SELECT Field.N.value('(text())[1]', 'nvarchar(500)') AS PositionPrefix FROM 
	@XMLCONTENT.nodes('/AdHocSAPHANARequest/PositionPrefix') AS Field (N) ) E

	SELECT @positionText =  E.PositionText FROM 
	(
	SELECT Field.N.value('(text())[1]', 'nvarchar(500)') AS PositionText FROM 
	@XMLCONTENT.nodes('/AdHocSAPHANARequest/Position') AS Field (N) ) E
			
			
			
	INSERT INTO @tblCRequestRole(BUSINESSROLE,TechnicalRole,ENDPOINTNAME,EP_CODE)
	SELECT A.RoleName,item,@endpointsystem,@CURRENT_APPLN_TYPENAME FROM
	(
		SELECT M.RoleName,M.TechnicalRole from DI_SAPHANA_XLRolesMatrix M inner join @tblCurrentRequestEntitlements B on M.RoleName = B.Entitlement
		where m.EndpointSystemId = 	@endpointSystemId
	) as A CROSS APPLY [dbo].[Split](A.TechnicalRole,',')

	
	----FIND THE INDIRECT ROLE FROM POSITION -------------------
	IF LEN(ISNULL(@positionText,''))>0
	BEGIN
			SET @TEMP_POS_CODE = ''
			SET @TEMP_POS_CODE = (SELECT TOP 1  Position FROM DI_SAPHANA_XLPositionsMatrix WHERE EndpointSystemId = @endpointSystemId AND PositionText=@positionText )
						
			INSERT INTO @tblCRequestRole(POSITION,TechnicalRole,BUSINESSROLE,ENDPOINTNAME,EP_CODE)
			SELECT @positionText,[ROLE],ISNULL(M.ROLENAME,DESCR),@endpointsystem,@CURRENT_APPln from dbo.fnSAPHANAGetRoleFromPosition(@endpointSystemId,@TEMP_POS_CODE) AS A
			LEFT JOIN 
			(
			SELECT A.RoleName,REPLACE(ITEM,CHAR(9),'') AS TECROLE FROM DI_SAPHANA_XLRolesMatrix A CROSS APPLY DBO.Split(A.TechnicalRole,',')  
			where EndpointSystemId = 	@endpointSystemId
			)AS M ON A.ROLE = M.TECROLE
	END
			---CURRENT REQUEST NEW ACCOUNT AND AMENTMENTADD-REALLOCATE START---
			--BEGIN

			---CURRENT SYSTEM REQUEST CONFLICT ----
			INSERT INTO @tblConflictBRoles (BRole,TRole,CBRole,CTRole,ConflictingRemarks,ENDPOINTNAME,EP_APPLNCODE,FROMCurrentRequestPosition,Position)
			SELECT distinct
			ConflictingBusinessRole,ConflictingTechnicalRole,COALESCE(B.BUSINESSROLE, m.BusinessRole), m.TechnicalRole,m.ConflictingRemarks,@endpointsystem,B.EP_CODE,
			CASE WHEN (B.TechnicalRole = M.TechnicalRole AND B.POSITION IS NOT NULL) THEN 1 ELSE 0 END,B.POSITION
			FROM DI_SAP_SODConflictingRole M INNER JOIN @tblCRequestRole B ON M.TechnicalRole = B.TechnicalRole where M.EndpointSystemName=B.EP_CODE
			

			INSERT INTO @tblConflictBRoles (BRole,TRole,CBRole,CTRole,ConflictingRemarks,ENDPOINTNAME,EP_APPLNCODE,FROMCurrentRequestPosition,Position)
			SELECT DISTINCT
			m.BusinessRole, m.TechnicalRole,COALESCE(B.BUSINESSROLE,ConflictingBusinessRole),ConflictingTechnicalRole,m.ConflictingRemarks,@endpointsystem,B.EP_CODE,
			CASE WHEN (B.TechnicalRole = M.ConflictingTechnicalRole AND B.POSITION IS NOT NULL) THEN 1 ELSE 0 END,B.POSITION
			FROM DI_SAP_SODConflictingRole M INNER JOIN @tblCRequestRole B ON M.ConflictingTechnicalRole = B.TechnicalRole
			WHERE M.EndpointSystemName=B.EP_CODE
			
			IF @debug = 1
			BEGIN	
					SELECT * FROM @tblConflictBRoles
			

					SELECT 'REQUESTED ROLE'
					SELECT * FROM @tblCRequestRole

					SELECT 'Conflicting roles'
					SELECT * FROM @tblConflictBRoles
			END
			/*---FOR NEW ACCOUNT AND REALLOCATE------
				FOR REALLOCATION WE DO CLEARING OF EXISITING POSITION AND ROLES.HENCE NO NEED TO VALIDATE IN THE EXISITING REQUEST AND CURRENT ACCESS
			*/
			
			IF (@AdhocActionType = 1 or (@AdhocActionType = 2 AND @REALLOCATE <>'false' ) OR (@ACCOUNTTYPE = 1 AND @AdhocActionType = 2 AND LEN(LTRIM(RTRIM(ISNULL(@POSPREFIX,'')))) > 0 AND LEN(LTRIM(RTRIM(ISNULL(@ACCOUNTNAME,'')))) > 0 AND @ACCOUNTNAME NOT LIKE (@POSPREFIX+'%')) )
			BEGIN
					SELECT A.ENDPOINTNAME,A.FROMCurrentRequestPosition,A.Position,A.CBRole,A.CTRole,R.POSITION AS REQPOSITION,R.BUSINESSROLE,R.TechnicalRole,A.ConflictingRemarks
					INTO #TBLCURRENTREQ
					FROM @tblConflictBRoles A inner join @tblCRequestRole r ON A.TRole = R.TechnicalRole 
					WHERE A.ENDPOINTNAME = r.ENDPOINTNAME AND A.EP_APPLNCODE = R.EP_CODE AND EXISTS(SELECT 1 FROM DI_SAP_SODConflictingRole B  WHERE 
					B.TechnicalRole = A.TRole AND  A.EP_APPLNCODE = B.EndpointSystemName)


					INSERT INTO @RESULT(EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source],[ReqRoleForSorting])
					SELECT A.ENDPOINTNAME,CONCAT(CASE WHEN A.FROMCurrentRequestPosition =1 THEN ' POSITION: '+A.Position+'(Technical Role)' ELSE ' ' END,A.CBRole,'</b> [',A.CTRole,']'),
					CONCAT(CASE WHEN LEN(LTRIM(RTRIM(ISNULL(A.REQPOSITION,'')))) > 0 THEN 'POSITION: '+A.REQPOSITION+' ' ELSE '' END,A.BUSINESSROLE,'</b>[',A.TechnicalRole,']'),A.ConflictingRemarks,'Current Request',
					A.CTRole
					FROM (
					SELECT A.ENDPOINTNAME,A.FROMCurrentRequestPosition,A.Position,A.CBRole,A.CTRole,A.REQPOSITION AS REQPOSITION,A.BUSINESSROLE,A.TechnicalRole,A.ConflictingRemarks FROM #TBLCURRENTREQ A WHERE A.CTRole > A.TechnicalRole OR NOT EXISTS(SELECT 1 FROM #TBLCURRENTREQ B WHERE B.CTRole = A.TechnicalRole AND B.TechnicalRole = A.CTRole AND B.ENDPOINTNAME = A.ENDPOINTNAME )
					)AS A

					SELECT EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source] INTO #TBLFINALRESILTTBL FROM @RESULT ORDER BY EndpointName DESC,[ReqRoleForSorting],Id

					SELECT DISTINCT EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source] FROM #TBLFINALRESILTTBL

					IF OBJECT_ID('tempdb..#TBLFINALRESILTTBL') IS NOT NULL
					BEGIN
							DROP TABLE #TBLFINALRESILTTBL
					END		

					IF OBJECT_ID('tempdb..#TBLCURRENTREQ') IS NOT NULL
					BEGIN
							DROP TABLE #TBLCURRENTREQ
					END
					RETURN;
			END
	
	--END
	
	---CURRENT REQUEST NEW ACCOUNT AND AMENTMENTADD-REALLOCATE END---
	IF (@isCurrentBulkRequest = 1 AND @AdhocActionType = 2  )
	BEGIN

		SELECT @endpointUserId =  E.EndpointUserId FROM DI_M_BulkRequestDetail E INNER JOIN DI_M_BulkRequest B on E.BulkRequestId = B.Id WHERE B.Id = @currentRequestId AND E.UserId = @userId

	END

	DECLARE @USR_CURRENT_POS TABLE(ID INT IDENTITY(1,1), ENDPOINTID BIGINT,ENDPOINTNAME NVARCHAR(MAX),POSITION NVARCHAR(32),ApplicationType TINYINT,POS_DESC  NVARCHAR(MAX))
	
	IF (@AdhocActionType = 2 AND LEN(ISNULL(@endpointUserId,'')) > 0)
	BEGIN

			
			SELECT @ACCOUNTNAME = UserLogonName FROM DI_SAPHANA_UserInfo WHERE ID = @endpointUserId
			
			declare @tblroles Table(rolecode nvarchar(max), roledesc nvarchar(max))
			
			
			IF(@applnType = 41)--EBS
			BEGIN
					INSERT INTO @tblroles(rolecode,roledesc)
					SELECT item,A.RoleName FROM
					(
						SELECT M.RoleName,M.TechnicalRole from DI_SAPHANA_XLRolesMatrix m
						where m.EndpointSystemId = 	@endpointSystemId
					) as A CROSS APPLY [dbo].[Split](A.TechnicalRole,',')

			END
			ELSE IF (@APPLNTYPE = 42)
			BEGIN
					INSERT INTO @tblroles(rolecode,roledesc)
					SELECT item,A.RoleName FROM
					(
						SELECT M.RoleName,M.TechnicalRole from DI_SAPHANA_XLRolesMatrix m
						where m.EndpointSystemId = 	@endpointSystemId
					) as A CROSS APPLY [dbo].[Split](A.TechnicalRole,',')

			END

			---CURRENT USER ACCESS(ROLE) FOR ENDPOINT----
			INSERT INTO @tblCurrentAccess(ENDPOINTID,ENDPOINTNAME,Entitlement,TECHNICALROLE,SOURCE,RequestId,POSITION,ApplicationType)
			SELECT @endpointSystemId,@endpointsystem,r.roledesc,E.Entitlement,'CurrentAccess',null,null,@applnType FROM DI_M_EntitlementReconcilation E INNER JOIN DI_M_AccountReconcilation A ON E.AccountReconcilationId = A.ID
			LEFT JOIN (SELECT rolecode,roledesc FROM @tblroles)as R ON E.Entitlement = R.rolecode
			WHERE A.EndpointSystemId = @endpointSystemId AND E.EndpointSystemId = @endpointSystemId AND A.IsDeleted = 0 AND A.IsLocked = 0 AND E.IsDeleted = 0 AND A.EndpointUserId IN(
			SELECT ID FROM DI_SAPHANA_UserInfo WHERE EndpointSystemId = @endpointSystemId AND UserLogonName = @ACCOUNTNAME  AND ID = @endpointUserId
			) AND E.EntitlementType = 1

			
			
			INSERT INTO @USR_CURRENT_POS(ENDPOINTID,ENDPOINTNAME,POSITION,ApplicationType,POS_DESC)
			SELECT @endpointSystemId,@endpointsystem,E.Entitlement,@applnType,EntitlementDescription FROM DI_M_EntitlementReconcilation E INNER JOIN DI_M_AccountReconcilation A ON E.AccountReconcilationId = A.ID
			WHERE A.EndpointSystemId = @endpointSystemId AND E.EndpointSystemId = @endpointSystemId AND A.IsDeleted = 0 AND A.IsLocked = 0 AND E.IsDeleted = 0 AND A.EndpointUserId IN(
			SELECT ID FROM DI_SAPHANA_UserInfo WHERE EndpointSystemId = @endpointSystemId AND UserLogonName = @ACCOUNTNAME AND ID = @endpointUserId
			) AND E.EntitlementType = 5

			IF(@ACCOUNTTYPE = 1 OR @ACCOUNTTYPE = 4)
			BEGIN
					---EXISTING PENDING REQUEST FOR SAME ENDPOINT---
					INSERT INTO @tblExistingXmlContent([source], [RequestId] ,xmlcontent,ENDPOINTID,ENDPOINTNAME,ApplicationType) 
					SELECT [Source],RequestId, CAST(EntitlementDetail As XML)  EntitlementDetails,ENDPOINTSYSTEMID,ENDPOINTNAME,@applnType  FROM 
					(
 
						SELECT 'Adhoc Request'  as [Source], accrrst.Id  AS RequestId, adhoc.EntitlementDetail,E.ID  AS ENDPOINTSYSTEMID,E.DisplayName AS ENDPOINTNAME
						FROM DI_M_AccessRequest AS accrrst 
						JOIN DI_M_AdHocAccessRequest AS adhoc ON accrrst.AdHocAccessRequestId = adhoc.Id 
						INNER JOIN DI_M_EndpointSystem E on adhoc.EndpointSystemId = e.Id
						WHERE   adhoc.RequesteeUserId = @userId AND  adhoc.EntitlementDetail like '%<AccName>'+@ACCOUNTNAME+'</AccName>%' AND
						adhoc.EndpointSystemId = @endpointSystemId AND  
						adhoc.AdhocActionType in (2) AND adhoc.AccountType = @ACCOUNTTYPE AND
						(accrrst.ProgressStatus = @progressStatus OR accrrst.ProgressStatus = 3 OR accrrst.ProgressStatus = 6 OR accrrst.ProgressStatus = 9 OR accrrst.ProgressStatus = 4) AND  adhoc.Id <> @currentRequestId

						UNION							  
						SELECT 'Bulk Request' as [Source], bulkReq.Id  AS RequestId,  bulkReq.EntitlementDetail,E.ID  AS ENDPOINTSYSTEMID,E.DisplayName
						FROM DI_M_BulkRequest AS bulkReq
						JOIN DI_M_BulkRequestDetail bulkdetail on bulkReq.Id = bulkdetail.BulkRequestId
						INNER JOIN DI_M_EndpointSystem E on bulkReq.EndpointSystemId = e.Id
						WHERE 
						bulkdetail.UserId = @userId AND
						bulkReq.EndpointSystemId = @endpointSystemId AND  
						bulkReq.AdhocActionType IN (2) AND
						(bulkReq.ProgressStatus = @progressStatus OR bulkReq.ProgressStatus = 3 OR bulkReq.ProgressStatus = 6 OR bulkReq.ProgressStatus = 9 OR bulkReq.ProgressStatus = 4) AND  bulkReq.Id <> @currentRequestId AND (@ACCOUNTTYPE = 1)
					)AS C
			END
			ELSE ---SHARED ACCOUNT AND SERVICE ACCOUNT
			BEGIN
					---EXISTING PENDING REQUEST FOR SAME ENDPOINT---
					INSERT INTO @tblExistingXmlContent([source], [RequestId] ,xmlcontent,ENDPOINTID,ENDPOINTNAME,ApplicationType) 
					SELECT [Source],RequestId, CAST(EntitlementDetail As XML)  EntitlementDetails,ENDPOINTSYSTEMID,ENDPOINTNAME,@applnType  FROM 
					(
 
						SELECT 'Adhoc Request'  as [Source], accrrst.Id  AS RequestId, adhoc.EntitlementDetail,E.ID  AS ENDPOINTSYSTEMID,E.DisplayName AS ENDPOINTNAME
						FROM DI_M_AccessRequest AS accrrst 
						JOIN DI_M_AdHocAccessRequest AS adhoc ON accrrst.AdHocAccessRequestId = adhoc.Id 
						INNER JOIN DI_M_EndpointSystem E on adhoc.EndpointSystemId = e.Id
						WHERE adhoc.EntitlementDetail like '%<AccName>'+@ACCOUNTNAME+'</AccName>%' AND
						adhoc.EndpointSystemId = @endpointSystemId AND  
						adhoc.AdhocActionType in (2) AND adhoc.AccountType = @ACCOUNTTYPE AND
						(accrrst.ProgressStatus = @progressStatus OR accrrst.ProgressStatus = 3 OR accrrst.ProgressStatus = 6 OR accrrst.ProgressStatus = 9 OR accrrst.ProgressStatus = 4)  AND  adhoc.Id <> @currentRequestId
					)AS C

			END
			

			---CURRENT USER ACCESS(ROLE) FOR DEPENDENT ENDPOINT----

			INSERT INTO @tblroles(rolecode,roledesc)
			SELECT item,A.RoleName FROM
			(
				SELECT M.RoleName,M.TechnicalRole from DI_SAPHANA_XLRolesMatrix m
				WHERE m.EndpointSystemId = 	@endpointSystemId
			) as A CROSS APPLY [dbo].[Split](A.TechnicalRole,',')

	END
	
	/**************************************************************** GET THE CURRENT ACCESS POSITION ROLE START********************************************************/
	
	

	DECLARE @CURCOUNT INT
	SELECT @CURCOUNT = COUNT(1) FROM @USR_CURRENT_POS
	DECLARE @INCR INT = 0
	DECLARE @CUR_APPTYPE TINYINT
	DECLARE @EPID INT
	DECLARE @EPNAME  NVARCHAR(MAX)
	DECLARE @POS_DESC  NVARCHAR(MAX)
	DECLARE @CUR_POS NVARCHAR(512)
	WHILE @INCR < @CURCOUNT 
	BEGIN
			SET @POS_DESC = ''
			SET @CUR_APPTYPE = 0
			SET @CUR_POS = ''
			SET @EPNAME = ''
			SET @EPID = NULL

			SELECT  @POS_DESC =POS_DESC, @CUR_APPTYPE = ApplicationType, @CUR_POS =POSITION,@EPNAME= ENDPOINTNAME,@EPID = ENDPOINTID FROM @USR_CURRENT_POS WHERE ID = @INCR + 1
			INSERT INTO @tblCurrentAccess(ENDPOINTID,ENDPOINTNAME,Entitlement,TECHNICALROLE,SOURCE,RequestId,POSITION,ApplicationType)
			SELECT @EPID,@EPNAME,DESCR,ROLE,'CurrentAccess',NULL,@POS_DESC,@CUR_APPTYPE FROM fnSAPHANAGetRoleFromPosition(@EPID,@CUR_POS)
			WHERE NOT EXISTS(select * from @tblCurrentAccess u2 where u2.ENDPOINTID = @EPID and u2.TECHNICALROLE = ROLE)
			
			
			SET @INCR = @INCR +	1	
	END
	
	
	/**************************************************************** GET THE CURRENT ACCESS POSITION ROLE END**********************************************************/
	DECLARE @RequestId BIGINT
	DECLARE @source NVARCHAR(200)
	DECLARE @exisitingEndpointName NVARCHAR(512) =''
	DECLARE @exisitingEndpointID BIGINT
	DECLARE @exisitingApptype tinyint
	DECLARE @exisiting_EndpointUserId BIGINT

	SET @i=0 
	SELECT @count = count(1) FROM @tblExistingXmlContent
	
	WHILE(@i < @count)
	BEGIN
			
			SET @XMLCONTENT = NULL
			SET @RequestId = 0
			SET @source = ''
			SET @exisitingEndpointID = 0
			SET @exisitingEndpointName = ''
			SET @exisitingApptype = 0
			SET @positionText = ''
			SET @REALLOCATE = ''
			SET @exisiting_EndpointUserId = 0


			SELECT    @XMLCONTENT = xmlcontent,@RequestId = RequestId, @source = source,@exisitingEndpointID=ENDPOINTID,@exisitingEndpointName= ENDPOINTNAME,@exisitingApptype = ApplicationType  FROM @tblExistingXmlContent WHERE id = @i+1
			

			
			
			---GET EXISTING REQUESTED ROLE---
			SELECT @positionText =  E.PositionText FROM 
			(
			SELECT Field.N.value('(text())[1]', 'nvarchar(500)') AS PositionText FROM 
			@XMLCONTENT.nodes('/AdHocSAPHANARequest/Position') AS Field (N) ) E

					
			SELECT @REALLOCATE =  E.IsReallocate FROM 
			(
			SELECT Field.N.value('(text())[1]', 'nvarchar(500)') AS IsReallocate FROM 
			@XMLCONTENT.nodes('/AdHocSAPHANARequest/IsReallocate') AS Field (N) ) E
			
			SELECT @exisiting_EndpointUserId =  E.EndpointUserId FROM 
			(
			SELECT Field.N.value('(text())[1]', 'bigint') AS EndpointUserId FROM 
			@XMLCONTENT.nodes('/AdHocSAPHANARequest/EndpointUserId') AS Field (N) ) E
					

			IF(@REALLOCATE ='false' )
			BEGIN
				----TAKE ONLY ROLE----
				INSERT INTO @tblExistingRequestEntitlements(Entitlement,TECHNICALROLE,RequestId,ApplicationType,ENDPOINTID,ENDPOINTNAME,SOURCE)
				SELECT A.RoleName,item,@RequestId,@exisitingApptype,@exisitingEndpointID,@exisitingEndpointName,@source FROM
				(
					SELECT M.RoleName,M.TechnicalRole from DI_SAPHANA_XLRolesMatrix M inner join 
					(
						SELECT DISTINCT   REPLACE(B.ITEM,CHAR(9),'') as Entitlement FROM 
						(SELECT Field.N.value('(Roles/text())[1]', 'nvarchar(500)') As Roles FROM 
						@XMLCONTENT.nodes('/*[local-name()=sql:variable("@applicationTypeXML")]') as Field (N) 
						) A CROSS APPLY dbo.split(A.Roles,@splitter) B
						WHERE A.Roles IS NOT NULL
					) AS B on M.RoleName = B.Entitlement
					where m.EndpointSystemId = 	@endpointSystemId AND  M.TechnicalRole IS NOT NULL
				) as A CROSS APPLY [dbo].[Split](A.TechnicalRole,',')
				WHERE item IS NOT NULL
			END

			
			IF(@REALLOCATE ='false' AND LEN(ISNULL(@positionText,''))>0)
			BEGIN
					
					SET @TEMP_POS_CODE = ''
					SET @TEMP_POS_CODE = (SELECT TOP 1 Position FROM DI_SAPHANA_XLPositionsMatrix WHERE PositionText=@positionText AND EndpointSystemId = @endpointSystemId)

					INSERT INTO @tblExistingRequestEntitlements(POSITION, Entitlement,TECHNICALROLE,[SOURCE],RequestId,ENDPOINTID,ENDPOINTNAME,ApplicationType)
					SELECT DISTINCT  @positionText,ISNULL(M.ROLENAME,A.DESCR),A.ROLE,@source, @RequestId,@exisitingEndpointID,@exisitingEndpointName,@exisitingApptype
					FROM dbo.fnSAPHANAGetRoleFromPosition(@exisitingEndpointID,@TEMP_POS_CODE) AS A
					LEFT JOIN 
					(
					SELECT A.RoleName,REPLACE(ITEM,CHAR(9),'') AS TECROLE FROM DI_SAPHANA_XLRolesMatrix A CROSS APPLY DBO.Split(A.TechnicalRole,',')  
					WHERE A.EndpointSystemId = 	@endpointSystemId AND Item IS NOT NULL
					)AS M ON A.ROLE = M.TECROLE
					
			END
			SET @i = @i + 1
	END

	IF @debug =1
	BEGIN
			SELECT 'CURRENT ACCESS DETAILS'
			SELECT * FROM @tblCurrentAccess
			SELECT 'CURRENT ACCESS PSOTION'
			SELECT * FROM @USR_CURRENT_POS
			SELECT 'PENDIGN REQUEST'
			SELECT * FROM @tblExistingRequestEntitlements
	END
	
	
	----CURRENT REQUEST----
	SELECT A.ENDPOINTNAME,A.FROMCurrentRequestPosition,A.Position,A.CBRole,A.CTRole,R.POSITION AS REQPOSITION,R.BUSINESSROLE,R.TechnicalRole,A.ConflictingRemarks
	INTO #TBLCURRENTREQAMENDMENT
	FROM @tblConflictBRoles A inner join @tblCRequestRole r ON A.TRole = R.TechnicalRole 
	WHERE A.ENDPOINTNAME = r.ENDPOINTNAME AND A.EP_APPLNCODE = R.EP_CODE AND EXISTS(SELECT 1 FROM DI_SAP_SODConflictingRole B  WHERE 
	B.TechnicalRole = A.TRole AND  A.EP_APPLNCODE = B.EndpointSystemName)

	INSERT INTO @RESULT(EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source],[ReqRoleForSorting])
	SELECT A.ENDPOINTNAME,CONCAT(CASE WHEN A.FROMCurrentRequestPosition =1 THEN ' POSITION: '+A.Position+'(Technical Role)' ELSE ' ' END,A.CBRole,'</b> [',A.CTRole,']'),
	CONCAT(CASE WHEN LEN(LTRIM(RTRIM(ISNULL(A.REQPOSITION,'')))) > 0 THEN 'POSITION: '+A.REQPOSITION+' ' ELSE '' END,A.BUSINESSROLE,'</b>[',A.TechnicalRole,']'),A.ConflictingRemarks,'Current Request',A.CTRole
	FROM (
	SELECT A.ENDPOINTNAME,A.FROMCurrentRequestPosition,A.Position,A.CBRole,A.CTRole,A.REQPOSITION ,A.BUSINESSROLE,A.TechnicalRole,A.ConflictingRemarks FROM #TBLCURRENTREQAMENDMENT
	A WHERE A.CTRole > A.TechnicalRole OR NOT EXISTS(SELECT 1 FROM #TBLCURRENTREQAMENDMENT B WHERE B.CTRole = A.TechnicalRole AND B.TechnicalRole = A.CTRole AND B.ENDPOINTNAME = A.ENDPOINTNAME )
	)AS A ORDER BY A.ENDPOINTNAME,A.TechnicalRole

	IF OBJECT_ID('tempdb..#TBLCURRENTREQAMENDMENT') IS NOT NULL
	BEGIN
			DROP TABLE #TBLCURRENTREQAMENDMENT
	END
			

	----EXISTING REQUEST----
	SELECT A.ENDPOINTNAME,A.FROMCurrentRequestPosition,A.Position,A.CBRole,A.CTRole,R.POSITION AS REQPOSITION,r.Entitlement,R.TechnicalRole,A.ConflictingRemarks,R.RequestId
	INTO #TBLEXISTSINGREQ
	FROM @tblConflictBRoles A inner join @tblExistingRequestEntitlements r ON A.TRole = R.TECHNICALROLE 
	where A.ENDPOINTNAME = r.ENDPOINTNAME 

	INSERT INTO @RESULT(EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source],[ReqRoleForSorting])
	SELECT A.ENDPOINTNAME,CONCAT(CASE WHEN A.FROMCurrentRequestPosition =1 THEN ' POSITION: '+A.Position+'(Technical Role)' ELSE ' ' END,A.CBRole,'</b> [',A.CTRole,']'),
	CONCAT(CASE WHEN LEN(LTRIM(RTRIM(ISNULL(A.REQPOSITION,'')))) > 0 THEN 'POSITION: '+A.REQPOSITION+' ' ELSE '' END,A.Entitlement,' [',A.TechnicalRole,']'),A.ConflictingRemarks,('Existing Request -Id:'+CAST(A.RequestId as varchar)+')'),A.CTRole
	FROM
	(
		SELECT A.* FROM #TBLEXISTSINGREQ A WHERE A.CTRole >A.TECHNICALROLE OR NOT EXISTS(SELECT 1 FROM #TBLEXISTSINGREQ B WHERE B.CTRole = A.TECHNICALROLE AND B.TECHNICALROLE = A.CTRole AND B.ENDPOINTNAME = A.ENDPOINTNAME)
	)AS A ORDER BY A.ENDPOINTNAME,A.TechnicalRole

			
	IF OBJECT_ID('tempdb..#TBLEXISTSINGREQ') IS NOT NULL
	BEGIN
			DROP TABLE #TBLEXISTSINGREQ
	END
	----CURRENT ACCESS----
	SELECT A.ENDPOINTNAME,A.FROMCurrentRequestPosition,A.Position,A.CBRole,A.CTRole,R.POSITION AS REQPOSITION,R.Entitlement,R.TECHNICALROLE,A.ConflictingRemarks
	INTO #TBLCURRENTACCESSREQ
	FROM @tblConflictBRoles A inner join @tblCurrentAccess r ON A.TRole = R.TECHNICALROLE 
	where A.ENDPOINTNAME = r.ENDPOINTNAME 
			
	INSERT INTO @RESULT(EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source],[ReqRoleForSorting])
	SELECT A.ENDPOINTNAME,CONCAT(CASE WHEN A.FROMCurrentRequestPosition =1 THEN ' POSITION: '+A.Position+'(Technical Role)' ELSE ' ' END,A.CBRole,'</b> [',A.CTRole,']'),
	CONCAT(CASE WHEN LEN(LTRIM(RTRIM(ISNULL(A.REQPOSITION,'')))) > 0 THEN 'POSITION: '+A.REQPOSITION+' ' ELSE '' END,A.Entitlement,' [',A.TechnicalRole,']'),A.ConflictingRemarks,'Current Access',A.CTRole
	FROM
	(
		SELECT A.ENDPOINTNAME,A.FROMCurrentRequestPosition,A.Position,A.CBRole,A.CTRole,A.REQPOSITION,A.Entitlement,A.TECHNICALROLE,A.ConflictingRemarks FROM #TBLCURRENTACCESSREQ A WHERE A.CTRole >A.TECHNICALROLE OR NOT EXISTS(SELECT 1 FROM #TBLCURRENTACCESSREQ B WHERE B.CTRole = A.TECHNICALROLE AND B.TECHNICALROLE = A.CTRole AND B.ENDPOINTNAME = A.ENDPOINTNAME)
	)AS A ORDER BY A.ENDPOINTNAME,A.TechnicalRole
			
	IF OBJECT_ID('tempdb..#TBLCURRENTACCESSREQ') IS NOT NULL
	BEGIN
			DROP TABLE #TBLCURRENTACCESSREQ
	END

	SELECT EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source] INTO #TBLFINALRESILTTBLEXT FROM @RESULT ORDER BY EndpointName DESC,[ReqRoleForSorting],Id
	
	
	SELECT DISTINCT EndpointName,RequestedRole,ConflictedRole,ConflictRemarks,[Source] FROM #TBLFINALRESILTTBLEXT

	IF OBJECT_ID('tempdb..#TBLFINALRESILTTBLEXT') IS NOT NULL
	BEGIN
			DROP TABLE #TBLFINALRESILTTBLEXT
	END		

	END TRY
	BEGIN CATCH
		
		INSERT INTO DI_Log_Provisioning([LogLevel], [Message], [ExceptionMessage], [StackTrace], [ExceptionSource], [InnerExceptionMessage], [LogDate], [CreatedBy], [AccessRequestId], [EndpointSystemTypeId], [EndpointSystemTypeName], [EndpointSystemId])
		VALUES(1,'ERROR OCCURED USP_GetSAPSODConflicts',@@ERROR, ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_NUMBER(),GETDATE(),'System',null,null,null,null)
		
	END CATCH

END

GO


IF  EXISTS(select 1 from sys.objects where name='USP_SAPHANA_CRITICALTCODEREPORT')
BEGIN
DROP PROC  [dbo].USP_SAPHANA_CRITICALTCODEREPORT
END
GO

/*
NAME		:	USP_SAPHANA_CRITICALTCODEREPORT
DESC		:	GENERATE THE CRITICAL TCODE REPORT BASED ON USERNAME;	
EXEC USP_CRITICALTCODEREPORT 10
*/
CREATE proc [dbo].USP_SAPHANA_CRITICALTCODEREPORT
(
@ENDPOINTID BIGINT,
@USERNAME NVARCHAR(MAX)=''
)
AS
BEGIN

	SET NOCOUNT ON;
	DECLARE @ACCOUNTRECONID BIGINT
	DECLARE @ENDPOINT_USERID BIGINT
	DECLARE @DISPLAYNAME nVARCHAR(MAX)=''
	DECLARE @ACCOUNTNAME nVARCHAR(512)=''
	DECLARE @TECHNICALROLE nVARCHAR(MAX)=''
	DECLARE @DESCRIPTION nVARCHAR(MAX)=''
	DECLARE @POSITION nVARCHAR(MAX)=''
	DECLARE @ACCOUNTTYPE TINYINT
	DECLARE @ENDPOINT_NAME nVARCHAR(1024)=''
	DECLARE @USER_NAME nVARCHAR(MAX)=''
	DECLARE @USERDISPLAYNAME	nVARCHAR(MAX)=''
	DECLARE @AccountOwner BIGINT=0
	
	DECLARE @APPTYPE TINYINT

	DECLARE @CURRENTDATE DATETIME=GETDATE()
	SELECT @APPTYPE= ApplicationType,@ENDPOINT_NAME = DisplayName FROM DI_M_EndpointSystem WHERE ID = @ENDPOINTID 

	

	DECLARE @TOTALACCOUNT BIGINT=0

	CREATE TABLE #TEMPACCOUNTS(ID BIGINT IDENTITY(1,1),DISPLAYNAME NVARCHAR(MAX) NULL,ACCOUNTNAME NVARCHAR(512) NOT NULL,ACCOUNTRECONID BIGINT NOT NULL,ENDPOINTUSERID BIGINT,ACCOUNTTYPE TINYINT, [UserName] [nvarchar](max) null,
	[UserDisplayName] [nvarchar](max) null,USERID BIGINT NULL)

	IF LEN(ISNULL(@USERNAME,''))> 0
	BEGIN
			INSERT INTO #TEMPACCOUNTS(ACCOUNTRECONID,DISPLAYNAME,ACCOUNTNAME,ENDPOINTUSERID,ACCOUNTTYPE,[UserName],[UserDisplayName],USERID)
			SELECT A.ID,FULLNAME ,ACCOUNTNAME,EndpointUserId,AccountType,B.USERNAME,B.DisplayName,A.UserId  FROM DI_M_AccountReconcilation A LEFT JOIN DI_M_User B on A.UserId = B.ID WHERE A.EndpointSystemId = @ENDPOINTID AND IsDeleted = 0 AND IsLocked = 0 AND AccountName=@USERNAME
			AND A.ID IN(SELECT AccountReconcilationId FROM DI_M_EntitlementReconcilation WHERE EndpointSystemId = @ENDPOINTID AND IsDeleted = 0 AND EntitlementType IN(1,5))
			AND EndpointUserId IN(SELECT ID FROM DI_SAPHANA_UserInfo WHERE EndPointSystemId  = @ENDPOINTID AND UserLogonName=@USERNAME)
			SET @TOTALACCOUNT = @@ROWCOUNT
			
			DELETE FROM DI_SAPHANA_CriticalTcodeReport WHERE EndPointSystemId = @ENDPOINTID AND AccountName=@USERNAME
	END
	ELSE
	BEGIN
			INSERT INTO #TEMPACCOUNTS(ACCOUNTRECONID,DISPLAYNAME,ACCOUNTNAME,ENDPOINTUSERID,ACCOUNTTYPE,[UserName],[UserDisplayName],USERID)
			SELECT A.ID,FULLNAME ,ACCOUNTNAME,EndpointUserId,AccountType,B.USERNAME,B.DisplayName,A.UserId FROM DI_M_AccountReconcilation  A LEFT JOIN DI_M_User B on A.UserId = B.ID WHERE A.EndpointSystemId = @ENDPOINTID AND IsDeleted = 0 AND IsLocked = 0
			AND A.ID IN(SELECT AccountReconcilationId FROM DI_M_EntitlementReconcilation WHERE EndpointSystemId = @ENDPOINTID AND IsDeleted = 0 AND EntitlementType IN(1,5))
			AND EndpointUserId IN(SELECT ID FROM DI_SAPHANA_UserInfo WHERE EndPointSystemId  = @ENDPOINTID)
			SET @TOTALACCOUNT = @@ROWCOUNT
			
			DELETE FROM DI_SAPHANA_CriticalTcodeReport WHERE EndPointSystemId = @ENDPOINTID
	END
	
	--SELECT *FROM #TEMPACCOUNTS

	IF @TOTALACCOUNT > 0
	BEGIN
			DECLARE @INCR BIGINT=1
			WHILE @TOTALACCOUNT >= @INCR
			BEGIN
				
					 SET @AccountOwner = 0
					 SET @ENDPOINT_USERID = 0
					 SET @ACCOUNTRECONID = 0
					 SET @DISPLAYNAME =''
					 SET @TECHNICALROLE =''
					 SET @DESCRIPTION =''
					 SET @POSITION =''
					 SET @ACCOUNTTYPE =0
					 SET @ACCOUNTNAME = ''
					 SET @USER_NAME		= ''
					 SET @USERDISPLAYNAME = ''

					 SELECT @ACCOUNTRECONID		= ACCOUNTRECONID,
							@DISPLAYNAME		= DISPLAYNAME,
							@ACCOUNTNAME		= ACCOUNTNAME,
							@ENDPOINT_USERID	= ENDPOINTUSERID,
							@ACCOUNTTYPE		= ACCOUNTTYPE,
							@USERDISPLAYNAME	= USERDISPLAYNAME,
							@USER_NAME			= USERNAME,
							@AccountOwner		= USERID	
					 FROM	#TEMPACCOUNTS 
					 WHERE	ID = @INCR

					 
					 DECLARE @TEMP_ROLES TABLE(Position NVARCHAR(MAX) NULL,TECHNICAL_ROLE NVARCHAR(MAX),FromValue NVARCHAR(MAX),ToValue NVARCHAR(MAX), [DESCRIPTION] NVARCHAR(MAX))

					--FROM TECHNICALROLE---
					INSERT INTO @TEMP_ROLES(Position,TECHNICAL_ROLE,FromValue,ToValue,[DESCRIPTION])
					SELECT NULL AS Position, Entitlement,FromValue,LTRIM(RTRIM(ISNULL(ToValue,''))) as ToValue,R.ROLE_DESC  FROM DI_M_EntitlementReconcilation E INNER JOIN 
					(
						SELECT RoleName,FromValue,ToValue FROM DI_SAPHANA_RoleToAuthMap WHERE EndPointSystemId = @ENDPOINTID AND ObjectCode = 'S_TCODE' AND FieldCode = 'TCD' AND ProfileGeneratorVariant != 'X'

					)AS SR ON E.Entitlement = SR.RoleName 
					INNER JOIN DI_SAPHANA_ROLEINFO R ON E.Entitlement = R.ROLE_CODE
					WHERE AccountReconcilationId = @ACCOUNTRECONID AND IsDeleted = 0 AND EntitlementType = 1 AND R.EndpointSystemId = @ENDPOINTID

					

					DECLARE @ROLES TABLE(POSITION NVARCHAR(1024),ROLE NVARCHAR(MAX) NULL,DESCR NVARCHAR(MAX) NULL)
					--FROM POSITION---
					DECLARE @POSCOUNT INT = 0
					IF OBJECT_ID('tempdb..#TBLPOST') IS NOT NULL
					BEGIN
							DROP TABLE #TBLPOST
					END

					SELECT IDENTITY(INT,1,1) AS ID, Entitlement  INTO #TBLPOST FROM DI_M_EntitlementReconcilation WHERE AccountReconcilationId = @ACCOUNTRECONID AND IsDeleted = 0 AND EntitlementType = 5
					SET @POSCOUNT = @@ROWCOUNT

					DECLARE @POS NVARCHAR(100)=''
					SET @POS = ''

					WHILE @POSCOUNT > 0
					BEGIN
							SELECT @POS = Entitlement FROM #TBLPOST WHERE ID = @POSCOUNT
							--PRINT @ACCOUNTNAME
							SELECT @POSITION = PositionText FROM DI_SAPHANA_XLPositionsMatrix WHERE EndPointSystemId = @ENDPOINTID AND Position = @POS 

							---getrolesby position
							INSERT INTO @ROLES(POSITION,ROLE,DESCR)
							SELECT ISNULL(@POSITION,@POS),RelatedObjectCode,ROLE_DESC FROM (SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId = @ENDPOINTID AND ActualObjectCode = @POS AND RelatedObjectType='AG' AND ActualObjectType='S')AS A
							INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID
							--GetOrgByPosition--
							DECLARE @ORGUNIT NVARCHAR(512)=''
							SET @ORGUNIT  = (SELECT  TOP 1 RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND ActualObjectCode = @POS AND RelatedObjectType='O' AND ActualObjectType='S')

							IF LEN(ISNULL(@ORGUNIT,'')) > 0
							BEGIN
							
									--getrolesbyorg--
									INSERT INTO @ROLES(POSITION,ROLE,DESCR)
									SELECT ISNULL(@POSITION,@POS),RelatedObjectCode,ROLE_DESC FROM
									(SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectType='AG' AND ActualObjectType='O' AND ActualObjectCode = @ORGUNIT
									) AS A INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID
									--GETPARENTOTGBYORG
									SET @ORGUNIT  = (SELECT  TOP 1 ActualObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectCode = @ORGUNIT AND RelatedObjectType='O' AND ActualObjectType='O')

							END

							DECLARE @INCRE INT = 0
							DECLARE @ISPARENTEXISTS BIT = 1
							WHILE(@ISPARENTEXISTS = 1 AND LEN(ISNULL(@ORGUNIT,'')) > 0)
							BEGIN
									SET @INCRE = @INCRE + 1
									IF(@INCRE <= 5 AND LEN(ISNULL(@ORGUNIT,'')) > 0)
									BEGIN
											INSERT INTO @ROLES(POSITION, ROLE,DESCR)
											SELECT ISNULL(@POSITION,@POS),RelatedObjectCode,ROLE_DESC FROM
											(SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectType='AG' AND ActualObjectType='O' AND ActualObjectCode = @ORGUNIT
											) AS A INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID

											SET @ORGUNIT  = (SELECT  TOP 1 ActualObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectCode = @ORGUNIT AND RelatedObjectType='O' AND ActualObjectType='O')

									END
									ELSE 
									BEGIN
											SET @ISPARENTEXISTS = 0
									END

							END
							
							SET @POSCOUNT = @POSCOUNT - 1
					END


					IF EXISTS(SELECT 1 FROM @ROLES)
					BEGIN
					INSERT INTO @TEMP_ROLES(Position,TECHNICAL_ROLE,FromValue,[DESCRIPTION],ToValue)
					SELECT POSITION,ROLE AS Entitlement,FromValue,DESCR,ToValue FROM 
					(
						SELECT Distinct POSITION, ROLE,DESCR from @ROLES
					) AS A
					INNER JOIN (
						SELECT RoleName,FromValue,ToValue FROM DI_SAPHANA_RoleToAuthMap WHERE EndPointSystemId = @ENDPOINTID AND ObjectCode = 'S_TCODE' AND FieldCode = 'TCD' AND ProfileGeneratorVariant != 'X'
					)AS SR ON ROLE = SR.RoleName 
					END
					IF EXISTS(SELECT 1 FROM @TEMP_ROLES)
					BEGIN

						IF EXISTS(SELECT 1 FROM @TEMP_ROLES WHERE FromValue = '*')
						BEGIN
							INSERT INTO DBO.DI_SAPHANA_CriticalTcodeReport(EndPointSystemId,EndpointSystemName,AccountName,Displayname,[Transaction],[Description],BusinessRole, TechnicalRole,FromPosition,AccountType,createdBy, CreatedDate, [UserName],[UserDisplayName],[TransactionOwner],AccountOwnerId)
								SELECT distinct
									@ENDPOINTID,@ENDPOINT_NAME,@ACCOUNTNAME,@DISPLAYNAME,M.[Transaction],M.[TransactionDescription],ISNULL(D.RoleName,M.[DESCRIPTION]), M.TECHNICAL_ROLE,M.Position,@ACCOUNTTYPE,'System',@CURRENTDATE,@USER_NAME,@UserDisplayName,
									TransactionOwner,@AccountOwner FROM  
									(
										SELECT [Transaction],[TransactionDescription],TCODE_Code,TCODE_Desc,TECHNICAL_ROLE,Position,FromValue,[DESCRIPTION],TransactionOwner FROM 
										(
										SELECT M.[Transaction],M.[TransactionDescription],T.TCODE_Code,T.TCODE_Desc,M.TransactionOwner FROM DI_SAPHANA_XLCriticalTCodeMatrix M INNER JOIN [dbo].[DI_SAPHANA_TCODEINFO] T ON M.[Transaction] = T.TCODE_Code
										WHERE M.EndPointSystemId = @ENDPOINTID AND T.EndPointSystemId = @ENDPOINTID
										) AS MR 
										CROSS JOIN (SELECT TECHNICAL_ROLE,Position,FromValue,[DESCRIPTION] FROM @TEMP_ROLES WHERE FromValue = '*')AS B
									)AS M
									LEFT JOIN (SELECT ROLENAME,item as TechnicalRole FROM DI_SAPHANA_XLRolesMatrix CROSS APPLY dbo.Split(TechnicalRole,',') WHERE EndpointSystemId = @ENDPOINTID)AS D ON M.TECHNICAL_ROLE = D.TechnicalRole
						
					END
					
					IF EXISTS(SELECT 1 FROM @TEMP_ROLES WHERE FromValue <> '*' and LEN(LTRIM(RTRIM(ISNULL(ToValue,''))))> 0)
					BEGIN

							--- TCODE with in the Range ---
							IF EXISTS(SELECT 1 FROM DI_M_EndpointSystem WHERE Id = @ENDPOINTID AND ApplicationType IN(41,42))
							BEGIN
								INSERT INTO DBO.DI_SAPHANA_CriticalTcodeReport(EndPointSystemId,EndpointSystemName,AccountName,Displayname,[Transaction],[Description],BusinessRole, TechnicalRole,FromPosition,AccountType,createdBy, CreatedDate, [UserName],[UserDisplayName],[TransactionOwner],AccountOwnerId)
								SELECT 
								@ENDPOINTID,@ENDPOINT_NAME,@ACCOUNTNAME,@DISPLAYNAME,M.[Transaction],M.[TransactionDescription],ISNULL(D.RoleName,T.DESCRIPTION), T.TECHNICAL_ROLE,T.Position,@ACCOUNTTYPE,'System',@CURRENTDATE,@USER_NAME,@UserDisplayName,M.TransactionOwner,@AccountOwner FROM DI_SAPHANA_XLCriticalTCodeMatrix M 
								INNER JOIN [dbo].[DI_SAPHANA_TCODEINFO] B ON M.[Transaction] = B.TCODE_Code
								INNER JOIN @TEMP_ROLES T ON M.[Transaction] between T.FromValue and T.ToValue
								LEFT JOIN (SELECT ROLENAME,TechnicalRole FROM DI_SAPHANA_XLRolesMatrix
								WHERE  EndpointSystemId = @ENDPOINTID)AS D ON T.TECHNICAL_ROLE = D.TechnicalRole AND LEN(LTRIM(RTRIM(ISNULL(ToValue,''))))> 0 AND FromValue <> '*'
								
								UNION

								SELECT 
								@ENDPOINTID,@ENDPOINT_NAME,@ACCOUNTNAME,@DISPLAYNAME,M.[Transaction],M.[TransactionDescription],ISNULL(D.RoleName,T.DESCRIPTION), T.TECHNICAL_ROLE,T.Position,@ACCOUNTTYPE,'System',@CURRENTDATE,@USER_NAME,@UserDisplayName,M.TransactionOwner,@AccountOwner FROM DI_SAPHANA_XLCriticalTCodeMatrix M 
								INNER JOIN [dbo].[DI_SAPHANA_TCODEINFO] B ON M.[Transaction] = B.TCODE_Code
								INNER JOIN @TEMP_ROLES T ON M.[Transaction] = T.FromValue
								LEFT JOIN (SELECT ROLENAME,TechnicalRole FROM DI_SAPHANA_XLRolesMatrix
								WHERE EndpointSystemId = @ENDPOINTID)AS D ON T.TECHNICAL_ROLE = D.TechnicalRole AND LEN(LTRIM(RTRIM(ISNULL(ToValue,''))))= 0 AND FromValue <> '*'
								
							END
							

					END

					Else IF EXISTS(SELECT 1 FROM @TEMP_ROLES WHERE FromValue <> '*')
					BEGIN

							INSERT INTO DBO.DI_SAPHANA_CriticalTcodeReport(EndPointSystemId,EndpointSystemName,AccountName,Displayname,[Transaction],[Description], BusinessRole, TechnicalRole,FromPosition,AccountType,createdBy, CreatedDate, [UserName],[UserDisplayName],[TransactionOwner],AccountOwnerId)
							SELECT distinct
							@ENDPOINTID,@ENDPOINT_NAME,@ACCOUNTNAME,@DISPLAYNAME,M.[Transaction],M.[TransactionDescription],ISNULL(D.RoleName,T.DESCRIPTION),T.TECHNICAL_ROLE,T.Position,@ACCOUNTTYPE,'System',@CURRENTDATE,@USER_NAME,@UserDisplayName,M.TransactionOwner,@AccountOwner FROM DI_SAPHANA_XLCriticalTCodeMatrix M 
							INNER JOIN [dbo].[DI_SAPHANA_TCODEINFO] B ON M.[Transaction] = B.TCODE_Code
							INNER JOIN @TEMP_ROLES T ON M.[Transaction] = T.FromValue
							LEFT JOIN (SELECT ROLENAME,item as TechnicalRole FROM DI_SAPHANA_XLRolesMatrix CROSS APPLY dbo.Split(TechnicalRole,',')  WHERE EndpointSystemId = @ENDPOINTID )AS D ON T.TECHNICAL_ROLE = D.TechnicalRole
							WHERE T.FromValue <> '*'

					END
					
					END

					SET @INCR = @INCR + 1
					DELETE FROM @TEMP_ROLES
					DELETE FROM @ROLES
			END
		
	END

	IF OBJECT_ID('tempdb..#TBLPOST') IS NOT NULL
	BEGIN
			DROP TABLE #TBLPOST
	END
	IF OBJECT_ID('tempdb..#TEMPACCOUNTS') IS NOT NULL
	BEGIN
			DROP TABLE #TEMPACCOUNTS
	END

END


GO
IF  EXISTS(select 1 from sys.objects where name='USP_SAPHANA_SODCONFLICTING_REPORT')
BEGIN
DROP PROC  [dbo].USP_SAPHANA_SODCONFLICTING_REPORT
END
GO
/*
NAME		:	[USP_SAPHANA_SODCONFLICTING_REPORT]
DESC		:	GENERATE THE CONFLICTING ROLES REPORT BY ACCOUNTNAME;	
EXEC USP_SODCONFLICTING_REPORT 10,'SPECIAL_SEC'

*/

CREATE PROC [dbo].[USP_SAPHANA_SODCONFLICTING_REPORT]
(
@ENDPOINTID BIGINT,
@USERNAME NVARCHAR(512)='',
@DEBUG BIT = 0
)
AS
BEGIN

	SET NOCOUNT ON;
	DECLARE @AccountOwner BIGINT
	DECLARE @ACCOUNTRECONID BIGINT
	DECLARE @ENDPOINT_USERID BIGINT
	DECLARE @DISPLAYNAME nVARCHAR(MAX)=''
	DECLARE @ACCOUNTNAME nVARCHAR(512)=''
	DECLARE @TECHNICALROLE nVARCHAR(MAX)=''
	DECLARE @DESCRIPTION nVARCHAR(MAX)=''
	DECLARE @POSITION nVARCHAR(MAX)=''
	DECLARE @ACCOUNTTYPE TINYINT
	DECLARE @ENDPOINT_NAME nVARCHAR(1024)=''
	DECLARE @USER_NAME nVARCHAR(MAX)=''
	DECLARE @USERDISPLAYNAME	nVARCHAR(MAX)=''
	DECLARE @MODULE VARCHAR(52)=''
	DECLARE @APPTYPE TINYINT

	SELECT  @MODULE= ApplicationCode,@ENDPOINT_NAME = DisplayName FROM DI_M_EndpointSystem WHERE ID = @ENDPOINTID 
	
	

	DECLARE @TOTALACCOUNT BIGINT=0

	CREATE TABLE #TEMPACCOUNTS(ID BIGINT IDENTITY(1,1),DISPLAYNAME NVARCHAR(MAX) NULL,ACCOUNTNAME NVARCHAR(512) NOT NULL,ACCOUNTRECONID BIGINT NOT NULL,ENDPOINTUSERID BIGINT,ACCOUNTTYPE TINYINT, [UserName] [nvarchar](max) null,
	[UserDisplayName] [nvarchar](max) null,UserId BIGINT NULL)

	IF LEN(ISNULL(@USERNAME,''))> 0
	BEGIN
			DELETE FROM [dbo].[DI_SAPHANA_ConflictingRoleReport] WHERE EndPointSystemId = @ENDPOINTID AND AccountName=@USERNAME

			INSERT INTO #TEMPACCOUNTS(ACCOUNTRECONID,DISPLAYNAME,ACCOUNTNAME,ENDPOINTUSERID,ACCOUNTTYPE,[UserName],[UserDisplayName],UserId)
			SELECT DISTINCT A.ID,FULLNAME ,A.ACCOUNTNAME,A.EndpointUserId,AccountType,B.USERNAME,B.DisplayName,A.UserId  FROM DI_M_AccountReconcilation A INNER JOIN DI_M_EntitlementReconcilation E ON A.ID = E.AccountReconcilationId
			LEFT JOIN  DI_M_User B on A.UserId = B.ID
			WHERE A.EndpointSystemId = @ENDPOINTID  AND E.EndpointSystemId = @ENDPOINTID AND A.ISDELETED = 0 AND A.ISLOCKED = 0 AND A.AccountName=@USERNAME 
			AND E.IsDeleted = 0 AND E.EntitlementType IN(1,5)  AND A.EndpointUserId IN(SELECT ID FROM DI_SAPHANA_UserInfo WHERE EndPointSystemId  = @ENDPOINTID AND UserLogonName=@USERNAME)
			AND A.AccountName=@USERNAME
			SET @TOTALACCOUNT = @@ROWCOUNT
	END
	ELSE
	BEGIN
			

			DELETE FROM [dbo].[DI_SAPHANA_ConflictingRoleReport] WHERE EndPointSystemId = @ENDPOINTID

			INSERT INTO #TEMPACCOUNTS(ACCOUNTRECONID,DISPLAYNAME,ACCOUNTNAME,ENDPOINTUSERID,ACCOUNTTYPE,[UserName],[UserDisplayName],UserId)
			SELECT DISTINCT A.ID,FULLNAME ,A.ACCOUNTNAME,A.EndpointUserId,AccountType,B.USERNAME,B.DisplayName,A.UserId   FROM DI_M_AccountReconcilation A INNER JOIN DI_M_EntitlementReconcilation E ON A.ID = E.AccountReconcilationId
			INNER JOIN DI_SAPHANA_UserInfo SAPU ON A.EndpointUserId = SAPU.ID
			LEFT JOIN  DI_M_User B on A.UserId = B.ID
			WHERE A.EndpointSystemId = @ENDPOINTID  AND E.EndpointSystemId = @ENDPOINTID AND A.ISDELETED = 0 AND A.ISLOCKED = 0 AND E.IsDeleted = 0
			AND E.EntitlementType IN(1,5) AND  A.AccountName = SAPU.UserLogonName AND SAPU.EndPointSystemId = @ENDPOINTID
			ORDER BY A.FULLNAME
			SET @TOTALACCOUNT = @@ROWCOUNT
			
	END

	IF @TOTALACCOUNT > 0
	BEGIN
			
			DECLARE @INCR BIGINT=1
			WHILE @TOTALACCOUNT >= @INCR
			BEGIN
				
					 SET @AccountOwner = 0
					 SET @ENDPOINT_USERID = 0
					 SET @ACCOUNTRECONID = 0
					 SET @DISPLAYNAME =''
					 SET @TECHNICALROLE =''
					 SET @DESCRIPTION =''
					 SET @POSITION =null
					 SET @ACCOUNTTYPE =0
					 SET @ACCOUNTNAME = ''	 
					 SET @USER_NAME		= ''
					 SET @USERDISPLAYNAME = ''

					 SELECT @ACCOUNTRECONID		= ACCOUNTRECONID,
							@DISPLAYNAME		= DISPLAYNAME,
							@ACCOUNTNAME		= ACCOUNTNAME,
							@ENDPOINT_USERID	= ENDPOINTUSERID,
							@ACCOUNTTYPE		= ACCOUNTTYPE,
							@USERDISPLAYNAME	= USERDISPLAYNAME,
							@USER_NAME			= USERNAME,
							@AccountOwner		= USERID
					 FROM	#TEMPACCOUNTS 
					 WHERE	ID = @INCR
					
					 --PRINT @ACCOUNTNAME
					DECLARE @ROLES TABLE(ACCOUNTNAME NVARCHAR(MAX), POSITION NVARCHAR(1024) NULL,ROLE NVARCHAR(MAX) NULL,DESCR NVARCHAR(MAX) NULL)
					
					INSERT INTO @ROLES(ACCOUNTNAME,POSITION,ROLE,DESCR)
					SELECT	@ACCOUNTNAME,NULL, E.Entitlement,E.EntitlementDescription
					FROM DI_M_EntitlementReconcilation E
					WHERE AccountReconcilationId = @ACCOUNTRECONID AND EndpointSystemId = @ENDPOINTID AND IsDeleted = 0 AND ENTITLEMENTTYPE = 1
					--FROM POSITION---
					DECLARE @POSCOUNT INT = 0
					IF OBJECT_ID('tempdb..#TBLPOST') IS NOT NULL
					BEGIN
							DROP TABLE #TBLPOST
					END
					SET @POSCOUNT = 0
					SELECT IDENTITY(INT,1,1) AS ID, Entitlement  INTO #TBLPOST FROM DI_M_EntitlementReconcilation WHERE AccountReconcilationId = @ACCOUNTRECONID AND IsDeleted = 0 AND EntitlementType = 5
					SET @POSCOUNT = @@ROWCOUNT

					DECLARE @POS NVARCHAR(100)=''
					WHILE @POSCOUNT > 0
					BEGIN
							SET @POSITION = NULL
							SELECT @POS = Entitlement FROM #TBLPOST WHERE ID = @POSCOUNT
							
							SELECT @POSITION = PositionText FROM DI_SAPHANA_XLPositionsMatrix WHERE EndpointSystemId = @ENDPOINTID AND Position = @POS

							IF (LEN(ISNULL(@POSITION,'')) = 0)
							BEGIN
									SET @POSITION = 'POSITION:'+@POS+'NOT FOUND IN MATRIX'
							END
							---getrolesby position
							INSERT INTO @ROLES(ACCOUNTNAME,POSITION,ROLE,DESCR)
							SELECT @ACCOUNTNAME, ISNULL(@POSITION,@POS),RelatedObjectCode,ROLE_DESC FROM (SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId = @ENDPOINTID AND ActualObjectCode = @POS AND RelatedObjectType='AG' AND ActualObjectType='S')AS A
							INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID
							--GetOrgByPosition--
							DECLARE @ORGUNIT NVARCHAR(512)=''
							SET @ORGUNIT  = (SELECT  TOP 1 RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND ActualObjectCode = @POS AND RelatedObjectType='O' AND ActualObjectType='S')

							IF LEN(ISNULL(@ORGUNIT,'')) > 0
							BEGIN
							
									--getrolesbyorg--
									INSERT INTO @ROLES(ACCOUNTNAME,POSITION,ROLE,DESCR)
									SELECT @ACCOUNTNAME,ISNULL(@POSITION,@POS),RelatedObjectCode,ROLE_DESC FROM
									(SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectType='AG' AND ActualObjectType='O' AND ActualObjectCode = @ORGUNIT
									) AS A INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID
									--GETPARENTOTGBYORG
									SET @ORGUNIT  = (SELECT  TOP 1 ActualObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectCode = @ORGUNIT AND RelatedObjectType='O' AND ActualObjectType='O')

							END

							DECLARE @INCRE INT = 0
							DECLARE @ISPARENTEXISTS BIT = 1
							WHILE(@ISPARENTEXISTS = 1 AND LEN(ISNULL(@ORGUNIT,'')) > 0)
							BEGIN
									SET @INCRE = @INCRE + 1
									IF(@INCRE <= 5 AND LEN(ISNULL(@ORGUNIT,'')) > 0)
									BEGIN
											INSERT INTO @ROLES(ACCOUNTNAME,POSITION,ROLE,DESCR)
											SELECT @ACCOUNTNAME,@POSITION,RelatedObjectCode,ROLE_DESC FROM
											(SELECT RelatedObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectType='AG' AND ActualObjectType='O' AND ActualObjectCode = @ORGUNIT
											) AS A INNER JOIN DI_SAPHANA_ROLEINFO R ON A.RelatedObjectCode = R.ROLE_CODE WHERE EndPointSystemId = @ENDPOINTID

											SET @ORGUNIT  = (SELECT  TOP 1 ActualObjectCode FROM DI_SAPHANA_SAPHRP1001 WHERE EndpointSystemId=@ENDPOINTID AND RelatedObjectCode = @ORGUNIT AND RelatedObjectType='O' AND ActualObjectType='O')

									END
									ELSE 
									BEGIN
											SET @ISPARENTEXISTS = 0
									END

							END

							SET @POSCOUNT = @POSCOUNT - 1
					END


					DECLARE @CURRENTACCESS TABLE(
					[BusinessRole] [nvarchar](max) NULL,
					[TechnicalRole] [nvarchar](max) NULL,
					[REQ_Position] [nvarchar](max) NULL,
					[ConflictingRole] [nvarchar](max) NULL,
					[ConflictingTechnicalRole] [nvarchar](max) NULL,
					[SoDRemarks] [nvarchar](max) NULL,
					[SODOwner] [nvarchar](max) null,
					ISCURRENTPOSITION BIT DEFAULT(0)
					)


					INSERT INTO @CURRENTACCESS(BusinessRole,TechnicalRole,REQ_Position,ConflictingRole,ConflictingTechnicalRole,SoDRemarks,ISCURRENTPOSITION,[SODOwner])
					SELECT 
					M.ConflictingBusinessRole,M.ConflictingTechnicalRole,B.POSITION,M.BusinessRole,M.TechnicalRole,M.ConflictingRemarks,CASE WHEN B.ROLE = M.TechnicalRole AND B.POSITION IS NOT NULL THEN 1 ELSE 0 END,SODOwner
					FROM DI_SAP_SODConflictingRole M INNER JOIN @ROLES B ON M.TechnicalRole = B.ROLE where M.EndpointSystemName=@MODULE

					INSERT INTO @CURRENTACCESS(BusinessRole,TechnicalRole,REQ_Position,ConflictingRole,ConflictingTechnicalRole,SoDRemarks,ISCURRENTPOSITION,[SODOwner])
					SELECT 
					M.BusinessRole,M.TechnicalRole,B.POSITION,M.ConflictingBusinessRole,M.ConflictingTechnicalRole,M.ConflictingRemarks,CASE WHEN B.ROLE = M.ConflictingTechnicalRole AND B.POSITION IS NOT NULL THEN 1 ELSE 0 END,SODOwner
					FROM DI_SAP_SODConflictingRole M INNER JOIN @ROLES B ON M.ConflictingTechnicalRole = B.ROLE where M.EndpointSystemName=@MODULE

					IF OBJECT_ID('tempdb..#TBLRESULT') IS NOT NULL
					BEGIN
							DROP TABLE #TBLRESULT
					END
					SELECT A.ISCURRENTPOSITION,A.REQ_Position,A.ConflictingRole,A.ConflictingTechnicalRole,A.BusinessRole,A.TechnicalRole,R.POSITION,A.SoDRemarks,A.SODOwner INTO #TBLRESULT
					 FROM @CURRENTACCESS A INNER JOIN @ROLES R ON A.TechnicalRole = R.ROLE

					 INSERT INTO [dbo].DI_SAPHANA_ConflictingRoleReport(EndPointSystemId,EndpointSystemName,AccountName,Displayname,AccountType,BusinessRole,TechnicalRole,
						ConflictingRole,ConflictingTechnicalRole,From_Position,SoDRemarks,CreatedBy,CreatedDate,ConflictingPosition,UserName,UserDisplayName,[SODOwner],[AccountOwnerId])

					SELECT distinct A.EndPointSystemId,A.EndpointSystemName,A.AccountName,A.Displayname,A.AccountType,A.BusinessRole,A.TechnicalRole, A.ConflictingRole,A.ConflictingTechnicalRole,A.Position,
					A.SoDRemarks,A.CREATEDBY,A.CREATEDDATE,A.ConflictingPosition,A.UserName,A.UserDisplayName,A.SODOwner,A.AccountOwner 
					FROM
					(
						SELECT @ENDPOINTID as EndPointSystemId,@ENDPOINT_NAME as EndpointSystemName,@ACCOUNTNAME as AccountName,
						@DISPLAYNAME as Displayname,@ACCOUNTTYPE as AccountType,A.BusinessRole,A.TechnicalRole, A.ConflictingRole,A.ConflictingTechnicalRole,A.Position,A.SoDRemarks,'SYSTEM' AS CREATEDBY,
						GETDATE() AS CREATEDDATE,A.REQ_Position as ConflictingPosition, @USER_NAME as UserName,@USERDISPLAYNAME as UserDisplayName,A.SODOwner,@AccountOwner as AccountOwner
						FROM #TBLRESULT A WHERE A.ConflictingTechnicalRole > A.TechnicalRole OR NOT EXISTS(SELECT 1 FROM #TBLRESULT B WHERE B.ConflictingTechnicalRole = A.TechnicalRole AND B.TechnicalRole = A.ConflictingTechnicalRole )
					)AS A

					IF @DEBUG = 1
					BEGIN
						SELECT * FROM @CURRENTACCESS
						SELECT * FROM @ROLES
						SELECT * FROM #TEMPACCOUNTS
						SELECT * FROM #TBLRESULT

					END
					DELETE FROM @CURRENTACCESS
					DELETE FROM @ROLES

					SET @INCR = @INCR + 1
			END
		
	END
	IF OBJECT_ID('tempdb..#TBLRESULT') IS NOT NULL
	BEGIN
			DROP TABLE #TBLRESULT
	END
	IF OBJECT_ID('tempdb..#TBLPOST') IS NOT NULL
	BEGIN
			DROP TABLE #TBLPOST
	END
	IF OBJECT_ID('tempdb..#TEMPACCOUNTS') IS NOT NULL
	BEGIN
			DROP TABLE #TEMPACCOUNTS
	END

END


GO
